insert into public.price_params (key, position, grp, label, unit, value, source, source_url, source_date) values
  ('margin_wholesale_pct', 1, 'Margini', 'Margine all''ingrosso (ristoranti)', '%', 40, 'Proposta di Claude: copre le tue ore (non contate nei costi), gli invenduti oltre lo scarto e il rischio di un raccolto andato male. Da rivedere dopo il test.', null, null),
  ('margin_retail_pct', 2, 'Margini', 'Margine al dettaglio (privati)', '%', 100, 'Proposta di Claude: la vendita al dettaglio costa più tempo per kg (confezioni piccole, consegne singole, spiegazioni). Da rivedere dopo il test.', null, null),
  ('loss_pct', 3, 'Produzione', 'Scarto (funghi non vendibili)', '%', 10, 'Ipotesi: funghi rovinati, troppo aperti o non venduti in tempo.', null, null),
  ('packaging_eur_kg', 4, 'Produzione', 'Imballaggio', '€/kg', 0.3, 'Ipotesi: cassetta o vaschetta ed etichetta. Da sostituire con il prezzo vero quando li compri.', null, null),
  ('space_kg', 5, 'Locale', 'Capacità del locale di fruttificazione', 'kg di substrato', 112, 'Ipotesi: uno scaffale 90×45 cm a 4 ripiani con circa 8 balle da 14 kg dentro una mini serra.', null, null),
  ('energy_eur_kwh', 6, 'Locale', 'Prezzo dell''energia elettrica', '€/kWh', 0.4343, 'ARERA, prezzo di riferimento per i clienti vulnerabili dal 1° ottobre 2026, tasse incluse (43,43 c€/kWh).', 'https://www.arera.it/comunicati-stampa/dettaglio/elettricita-maggior-tutela-373-nel-iv-trimestre-2026-per-i-clienti-vulnerabili', '2026-09-29'::date),
  ('humidifier_w', 7, 'Locale', 'Umidificatore: potenza', 'W', 30, 'Ipotesi: umidificatore a ultrasuoni domestico. Leggi la potenza sull''etichetta del tuo.', null, null),
