  ('led_w', 9, 'Locale', 'Luce LED: potenza', 'W', 10, 'Ipotesi: una striscia LED bianca.', null, null),
  ('led_h', 10, 'Locale', 'Luce LED: ore al giorno', 'h', 12, 'Circa 12 ore di luce al giorno per i Pleurotus (parametri raccolti il 2 novembre).', null, null),
