  ('fan_h', 12, 'Locale', 'Ventola: ore al giorno', 'h', 8, 'Ipotesi.', null, null),
  ('heater_w', 13, 'Locale', 'Riscaldatore: potenza', 'W', 400, 'Ipotesi: piccolo riscaldatore con termostato dentro la mini serra.', null, null),
  ('heater_h_per_c', 14, 'Locale', 'Riscaldatore: ore al giorno per ogni °C che manca', 'h/°C', 1.5, 'Ipotesi grezza: da tarare con le tue misure della prima stagione.', null, null),
  ('water_eur_month', 15, 'Locale', 'Acqua per il locale', '€/mese', 1, 'Ipotesi: pochi litri al giorno per l''umidificatore.', null, null),
