insert into public.varieties (id, position, public, data, list_wholesale, list_retail, list_updated_at) values
  ('pleurotus-ostreatus', 1, true, '{"id":"pleurotus-ostreatus","commonName":"Pleurotus (orecchione, gelone)","scientificName":"Pleurotus ostreatus","otherNames":"fungo ostrica","kitchen":"Carnoso e versatile: in padella con aglio e prezzemolo, alla griglia, impanato, nei primi e nei risotti. Regge bene la cottura e costa poco al piatto.","photo":{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus_ostreatus.jpg?width=800","page":"https://commons.wikimedia.org/wiki/File:Pleurotus_ostreatus.jpg","credit":"Wikimedia Commons"},"legal":"ammesso","legalNote":"N. 34 dell''elenco delle specie vendibili (DPR 376/1995).","supply":{"mode":"ingrosso","supplier":"Oasi Acquarossa (balla da 14 kg)","supplierUrl":"https://www.oasiacquarossa.it","baleKg":14,"balePrice":20,"shippingPerOrder":12,"balesPerOrder":2,"bulkEurPerKg":0.22,"bulkSupplier":"Substrato in platee da produttori del Sud (De Biasi, Funghitex, Fides, ex SAIPAN): €18–19 al quintale + €2–4 di trasporto. Trasporto in Calabria e ordine minimo da chiedere."},"shipDays":{"min":3,"max":6},"incubationDays":{"min":0,"max":0},"firstHarvestDays":{"min":10,"max":15},"fruitingDays":{"min":45,"max":60},"flushes":3,"yieldPct":{"min":10,"max":25},"incubation":{"t":{"min":18,"max":22},"rh":null},"fruiting":{"t":{"min":12,"max":18},"rh":{"min":85,"max":95}},"market":{"wholesale":{"min":2,"max":3.5},"retail":{"min":6,"max":8.63}},"sources":{"legal":{"text":"Elenco delle specie commercializzabili, DPR 376/1995 integrato con DGR Lazio 547/2022 (ASL Rieti)","url":"https://aslrieti.dev.laserromae.it/wp-content/uploads/fileadmin/user_upload/Documenti/modulistica/dipartimento-prevenzione/sian/Elenco_Specie_commercializzabili.pdf","date":"2026-11-02"},"supply":{"text":"Oasi Acquarossa: balla da 14 kg €19,90, due a €39,99. Spedizione non indicata: €12 a ordine è un''ipotesi da verificare al checkout.","url":"https://www.oasiacquarossa.it","date":"2026-11-02"},"bulk":{"text":"Rivista di Agraria 2023: substrato €18–19/q + €2–4/q di trasporto, resa 22–25% per un buon coltivatore","url":"https://www.rivistadiagraria.org/articoli/anno-2023/aspetti-riflessioni-sul-mondo-dei-funghi-pleurotus/?print=pdf","date":"2023-01-01"},"shipDays":{"text":"Ipotesi: spedizione dalla Sicilia, tempi non indicati dal venditore."},"incubationDays":{"text":"Ipotesi: balla venduta pronta. Chiedi al venditore se arriva già incubata."},"firstHarvestDays":{"text":"Giardineria/Acquaverde (kit Pleurotus): primi funghi dopo 10–15 giorni, più lenti sotto i 12 °C","date":"2026-11-02"},"fruitingDays":{"text":"Volate di 3–8 giorni con pause di 10–20 giorni, circa 3 volate in 45–60 giorni (ricerca del 2 novembre)","date":"2026-11-02"},"yieldPct":{"text":"100–200 kg per tonnellata di substrato umido (Ministero dell''agricoltura spagnolo, Infoagro); 22–25% per un buon coltivatore (Rivista di Agraria 2023)","url":"https://www.rivistadiagraria.org/articoli/anno-2023/aspetti-riflessioni-sul-mondo-dei-funghi-pleurotus/?print=pdf"},"fruiting":{"text":"Fruttificazione 12–18 °C (10–15 °C ottimo 13–15 °C secondo Rivista di Agraria), umidità 85–95%, CO2 sotto 0,06%, 5–10 ricambi d''aria l''ora","url":"https://www.rivistadiagraria.org/articoli/anno-2023/aspetti-riflessioni-sul-mondo-dei-funghi-pleurotus/?print=pdf"},"incubation":{"text":"Incubazione 18–22 °C per 15–20 giorni (ricerca del 2 novembre); umidità di incubazione non trovata"},"marketWholesale":{"text":"Bari, Borsa Merci 01/09/2026: Pleurotus €2,00–2,50/kg netto; Milano Foody 10/03/2026: €3,50; Torino CAAT 26/01/2026 e Caserta 27/04/2026: €3,30–3,50 (italiano, doppio strato, IVA esclusa)","url":"https://www.ba.camcom.it/articoli/allegato/2026/09/listino-ortofrutta-e-mandorle-01.09.2026.pdf","date":"2026-09-01"},"marketRetail":{"text":"Godoli (Forlì) €3,30/500 g = €6,60/kg; tiportolaspesa (Fano) €2,59/300 g = €8,63/kg; ilmercatodiviabosco €6/kg","date":"2026-11-02"}},"notes":"Con le balle comprate al dettaglio ogni kg costa troppo: servono per imparare. Il prezzo regge solo con il substrato all''ingrosso."}'::jsonb, 3.9, 5.6, now()),
  ('cardoncello', 2, true, '{"id":"cardoncello","commonName":"Cardoncello","scientificName":"Pleurotus eryngii","otherNames":"king oyster","kitchen":"Gambo sodo e saporito, quasi da carne: alla brace, a fette in padella, nei sughi e sotto le orecchiette. Il fungo della tradizione di Puglia e Basilicata.","photo":{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus_eryngii.jpg?width=800","page":"https://commons.wikimedia.org/wiki/File:Pleurotus_eryngii.jpg","credit":"Wikimedia Commons"},"legal":"ammesso","legalNote":"N. 33 dell''elenco delle specie vendibili (DPR 376/1995).","supply":{"mode":"balla","supplier":"Agraria Comand (balla piccola incubata, circa 3 kg)","supplierUrl":"https://www.agraria-comand.it/balla-incubata-fungo-cardoncello-pleurotus-eryngii.html","baleKg":3,"balePrice":10.95,"shippingPerOrder":12,"balesPerOrder":4,"bulkEurPerKg":null,"bulkSupplier":"Da chiedere a De Biasi (Murgia, Puglia), specializzati nel cardoncello: ifunghi.com."},"shipDays":{"min":2,"max":5},"incubationDays":{"min":0,"max":0},"firstHarvestDays":{"min":15,"max":20},"fruitingDays":{"min":10,"max":20},"flushes":1,"yieldPct":{"min":15,"max":25},"incubation":{"t":{"min":23,"max":27},"rh":null},"fruiting":{"t":{"min":12,"max":17},"rh":{"min":70,"max":85}},"market":{"wholesale":{"min":5,"max":6},"retail":{"min":24.95,"max":24.95}},"sources":{"legal":{"text":"Elenco delle specie commercializzabili, DPR 376/1995 integrato con DGR Lazio 547/2022 (ASL Rieti)","url":"https://aslrieti.dev.laserromae.it/wp-content/uploads/fileadmin/user_upload/Documenti/modulistica/dipartimento-prevenzione/sian/Elenco_Specie_commercializzabili.pdf","date":"2026-11-03"},"supply":{"text":"Agraria Comand: balla piccola incubata, circa 3 kg, €10,95. Costo di spedizione calcolato al checkout: €12 a ordine è un''ipotesi.","url":"https://www.agraria-comand.it/balla-incubata-fungo-cardoncello-pleurotus-eryngii.html","date":"2026-11-03"},"shipDays":{"text":"Agraria Comand: preparazione il mattino dopo l''ordine, spedizioni da martedì a venerdì, consegna in 24–48 ore","url":"https://www.agraria-comand.it/spedizioni-e-consegne","date":"2026-11-03"},"incubationDays":{"text":"La balla è venduta già incubata (Agraria Comand)"},"firstHarvestDays":{"text":"ifunghi.com (De Biasi): funghi dopo 15–20 giorni","url":"https://ifunghi.com/","date":"2026-11-03"},"fruitingDays":{"text":"Ipotesi: di solito una volata principale (Moonmoon et al. 2010 raccolgono una sola volata)"},"yieldPct":{"text":"Derivata: efficienza biologica 47–74% sul peso secco (Moonmoon et al. 2010) con substrato al 65% di umidità = circa 16–26% del peso umido","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3730573"},"incubation":{"text":"Incubazione al buio a 25 ± 2 °C (Moonmoon et al. 2010)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3730573"},"fruiting":{"text":"Fruttificazione 12–17 °C, umidità 70–85%, 180–250 lux (Moonmoon et al. 2010)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3730573"},"marketWholesale":{"text":"Bari, Borsa Merci 01/09/2026: cardoncelli €5,00–6,00/kg netto","url":"https://www.ba.camcom.it/articoli/allegato/2026/09/listino-ortofrutta-e-mandorle-01.09.2026.pdf","date":"2026-09-01"},"marketRetail":{"text":"Cortilia: cardoncelli bio del Südtirol, 200 g a €4,99 = €24,95/kg (un solo prezzo, biologico)","url":"https://www.cortilia.it/prodotti/funghi-cardoncelli-bio-del-sudtirol_113PROD0920","date":"2026-11-03"}},"notes":"Più difficile dell''orecchione e di solito una sola volata. Il prezzo al dettaglio trovato è uno solo e biologico: serve un secondo dato."}'::jsonb, null, null, null),
  ('pioppino', 3, true, '{"id":"pioppino","commonName":"Pioppino","scientificName":"Agrocybe aegerita","otherNames":"Cyclocybe cylindracea, Pholiota aegerita","kitchen":"Gambo croccante e profumo di bosco: trifolato, nei sughi, con la polenta, nei risotti e sulla pizza. Si cucina intero, a mazzetti.","photo":{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Agrocybe_aegerita.jpg?width=800","page":"https://commons.wikimedia.org/wiki/File:Agrocybe_aegerita.jpg","credit":"Wikimedia Commons"},"legal":"ammesso","legalNote":"N. 47 dell''elenco delle specie vendibili (DPR 376/1995), come Agrocybe aegerita (Pholiota aegerita).","supply":{"mode":"balla","supplier":"Agraria Comand (balla incubata, circa 12 kg)","supplierUrl":"https://www.agraria-comand.it/substrato-incubato-pioppino-pholiota-aegerita.html","baleKg":12,"balePrice":28.49,"shippingPerOrder":12,"balesPerOrder":2,"bulkEurPerKg":null,"bulkSupplier":""},"shipDays":{"min":2,"max":5},"incubationDays":{"min":0,"max":0},"firstHarvestDays":{"min":20,"max":30},"fruitingDays":{"min":20,"max":30},"flushes":2,"yieldPct":{"min":15,"max":30},"incubation":{"t":{"min":23,"max":25},"rh":null},"fruiting":{"t":{"min":12,"max":25},"rh":{"min":85,"max":90}},"market":{"wholesale":{"min":12.3,"max":12.5},"retail":null},"sources":{"legal":{"text":"Elenco delle specie commercializzabili, DPR 376/1995 integrato con DGR Lazio 547/2022 (ASL Rieti)","url":"https://aslrieti.dev.laserromae.it/wp-content/uploads/fileadmin/user_upload/Documenti/modulistica/dipartimento-prevenzione/sian/Elenco_Specie_commercializzabili.pdf","date":"2026-11-03"},"supply":{"text":"Agraria Comand: balla incubata di circa 12 kg, €28,49. Spedizione: €12 a ordine è un''ipotesi.","url":"https://www.agraria-comand.it/substrato-incubato-pioppino-pholiota-aegerita.html","date":"2026-11-03"},"shipDays":{"text":"Agraria Comand: consegna in 24–48 ore, spedizioni da martedì a venerdì","url":"https://www.agraria-comand.it/spedizioni-e-consegne","date":"2026-11-03"},"incubationDays":{"text":"La balla è venduta già incubata (Agraria Comand)"},"firstHarvestDays":{"text":"Ipotesi: il venditore non lo dice; nello studio di Asian Journal of Mycology i funghi maturano circa tre settimane dopo i primordi","url":"https://asianjournalofmycology.org/pdf/AJOM_5_1_3.pdf"},"fruitingDays":{"text":"La Mycosphère: due raccolte a 10–14 giorni di distanza","url":"https://lamycosphere.com/en/products/organic-piopino-cultivation-block","date":"2026-11-03"},"yieldPct":{"text":"La Mycosphère: blocco da 3 kg, 0,5–1 kg in 2–3 raccolte (17–33%)","url":"https://lamycosphere.com/en/products/organic-piopino-cultivation-block","date":"2026-11-03"},"incubation":{"text":"Colonizzazione a 23–25 °C in 9–14 giorni (Asian Journal of Mycology)","url":"https://asianjournalofmycology.org/pdf/AJOM_5_1_3.pdf"},"fruiting":{"text":"Agraria Comand: 12–25 °C, umidità 85–90%, sotto 12 °C rallenta e si ferma; La Mycosphère: ideale 16–18 °C","url":"https://www.agraria-comand.it/substrato-incubato-pioppino-pholiota-aegerita.html","date":"2026-11-03"},"marketWholesale":{"text":"Tridge, prezzi all''ingrosso nell''area di Verona: €12,30/kg (3/11/2024) e €12,50/kg (17/01/2025). Dato vecchio di quasi due anni.","url":"https://dir.tridge.com/prices/fresh-poplar-mushroom/IT","date":"2025-01-17"},"marketRetail":{"text":"Prezzo al dettaglio in Italia non trovato"}},"notes":"Il prezzo all''ingrosso è alto ma vecchio: va riverificato con un grossista o con gli chef."}'::jsonb, null, null, null),
  ('shiitake', 4, true, '{"id":"shiitake","commonName":"Shiitake","scientificName":"Lentinula edodes","otherNames":"Lentinus edodes","kitchen":"Sapore intenso e umami: saltato al wok, nei brodi e nei ramen, alla piastra, nei ripieni. Ottimo anche per piatti vegetariani e vegani.","photo":{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Shiitake_mushroom.jpg?width=800","page":"https://commons.wikimedia.org/wiki/File:Shiitake_mushroom.jpg","credit":"Wikimedia Commons"},"legal":"ammesso","legalNote":"N. 28 dell''elenco delle specie vendibili (DPR 376/1995), come Lentinus edodes.","supply":{"mode":"balla","supplier":"Agraria Comand (balla incubata, circa 10–11 kg)","supplierUrl":"https://www.agraria-comand.it/balla-incubata-fungo-shiitake-lentinus-edodes.html","baleKg":10.5,"balePrice":28.49,"shippingPerOrder":12,"balesPerOrder":2,"bulkEurPerKg":null,"bulkSupplier":"MìPulia (gruppo De Biasi, Puglia) coltiva shiitake: da chiedere se vende substrato."},"shipDays":{"min":2,"max":5},"incubationDays":{"min":0,"max":0},"firstHarvestDays":{"min":30,"max":90},"fruitingDays":{"min":14,"max":30},"flushes":null,"yieldPct":{"min":20,"max":28},"incubation":{"t":null,"rh":null},"fruiting":{"t":{"min":13,"max":21},"rh":{"min":80,"max":90}},"market":{"wholesale":{"min":9.5,"max":10.5},"retail":null},"sources":{"legal":{"text":"Elenco delle specie commercializzabili, DPR 376/1995 integrato con DGR Lazio 547/2022 (ASL Rieti)","url":"https://aslrieti.dev.laserromae.it/wp-content/uploads/fileadmin/user_upload/Documenti/modulistica/dipartimento-prevenzione/sian/Elenco_Specie_commercializzabili.pdf","date":"2026-11-03"},"supply":{"text":"Agraria Comand: balla incubata di circa 10–11 kg, €28,49. Spedizione: €12 a ordine è un''ipotesi.","url":"https://www.agraria-comand.it/balla-incubata-fungo-shiitake-lentinus-edodes.html","date":"2026-11-03"},"shipDays":{"text":"Agraria Comand: consegna in 24–48 ore, spedizioni da martedì a venerdì","url":"https://www.agraria-comand.it/spedizioni-e-consegne","date":"2026-11-03"},"incubationDays":{"text":"Venduta già incubata, ma la balla deve scurirsi prima di fruttificare: i tempi sono nei giorni alla prima raccolta"},"firstHarvestDays":{"text":"Agraria Comand: i primi funghi nascono 1–3 mesi dopo l''inizio delle bagnature","url":"https://www.agraria-comand.it/balla-incubata-fungo-shiitake-lentinus-edodes.html","date":"2026-11-03"},"fruitingDays":{"text":"SARE FNE16-847: fruttificazione in circa 2 settimane per volata; numero di volate non indicato","url":"https://projects.sare.org/project-reports/fne16-847/"},"yieldPct":{"text":"SARE FNE16-847: blocchi da 2,27 kg, 0,45–0,64 kg di funghi (20–28%)","url":"https://projects.sare.org/project-reports/fne16-847/"},"incubation":{"text":"SARE: incubazione di 8 settimane; temperatura di incubazione non trovata"},"fruiting":{"text":"SARE: 13–21 °C (55–70 °F) dopo uno shock a freddo di 24 ore, umidità circa 85%; Agraria Comand: 16–25 °C","url":"https://projects.sare.org/project-reports/fne16-847/"},"marketWholesale":{"text":"Tridge, prezzi all''ingrosso in Italia: €9,50/kg (3/02/2025) e €10,50/kg (14/02/2025). Dato vecchio di quasi due anni.","url":"https://dir.tridge.com/ko/prices/fresh-shiitake-mushroom/IT","date":"2025-02-14"},"marketRetail":{"text":"Prezzo al dettaglio del fresco in Italia non trovato"}},"notes":"Tempi lunghi e incerti: da 1 a 3 mesi prima dei primi funghi. Per le prenotazioni conta il caso peggiore."}'::jsonb, null, null, null),
  ('pleurotus-cornucopiae', 5, true, '{"id":"pleurotus-cornucopiae","commonName":"Gialletto","scientificName":"Pleurotus cornucopiae","otherNames":"pleurotus a cornucopia","kitchen":"Più delicato dell''orecchione, a ciuffi dal colore crema: in padella, nelle zuppe, come contorno. Tollera il caldo meglio degli altri Pleurotus.","photo":{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Cespi_di_funghi_Pleurotus_cornucopiae.jpg?width=800","page":"https://commons.wikimedia.org/wiki/File:Cespi_di_funghi_Pleurotus_cornucopiae.jpg","credit":"Wikimedia Commons"},"legal":"ammesso","legalNote":"N. 32 dell''elenco delle specie vendibili (DPR 376/1995).","supply":{"mode":"balla","supplier":"Agraria Comand (substrato incubato, circa 15 kg)","supplierUrl":"https://www.agraria-comand.it/substrato-incubato-gialletto-pleurotus-cornucopiae.html","baleKg":15,"balePrice":17.6,"shippingPerOrder":12,"balesPerOrder":2,"bulkEurPerKg":null,"bulkSupplier":""},"shipDays":{"min":2,"max":5},"incubationDays":{"min":0,"max":0},"firstHarvestDays":{"min":10,"max":15},"fruitingDays":{"min":45,"max":60},"flushes":null,"yieldPct":{"min":10,"max":25},"incubation":{"t":null,"rh":null},"fruiting":{"t":{"min":15,"max":30},"rh":{"min":85,"max":90}},"market":{"wholesale":null,"retail":null},"sources":{"legal":{"text":"Elenco delle specie commercializzabili, DPR 376/1995 integrato con DGR Lazio 547/2022 (ASL Rieti)","url":"https://aslrieti.dev.laserromae.it/wp-content/uploads/fileadmin/user_upload/Documenti/modulistica/dipartimento-prevenzione/sian/Elenco_Specie_commercializzabili.pdf","date":"2026-11-03"},"supply":{"text":"Agraria Comand: substrato incubato di circa 15 kg, €17,60. Spedizione: €12 a ordine è un''ipotesi.","url":"https://www.agraria-comand.it/substrato-incubato-gialletto-pleurotus-cornucopiae.html","date":"2026-11-03"},"shipDays":{"text":"Agraria Comand: consegna in 24–48 ore, spedizioni da martedì a venerdì","url":"https://www.agraria-comand.it/spedizioni-e-consegne","date":"2026-11-03"},"incubationDays":{"text":"Venduto già incubato (Agraria Comand)"},"firstHarvestDays":{"text":"Ipotesi: come l''orecchione, il venditore non lo dice"},"fruitingDays":{"text":"Ipotesi: come l''orecchione"},"yieldPct":{"text":"Ipotesi: come l''orecchione, il venditore non lo dice"},"incubation":{"text":"Non trovata"},"fruiting":{"text":"Agraria Comand: ideale 15–30 °C, umidità 85–90%; sotto 12 °C rallenta e si ferma","url":"https://www.agraria-comand.it/substrato-incubato-gialletto-pleurotus-cornucopiae.html","date":"2026-11-03"},"marketWholesale":{"text":"Prezzo specifico non trovato: i listini riportano solo \"Pleurotus\" senza specie"},"marketRetail":{"text":"Non trovato"}},"notes":"Molti dati sono ipotesi presi dall''orecchione. Utile per la stagione calda."}'::jsonb, null, null, null),
